      if (!f) { f = node('<iframe class="mc-preview-frame" title="preview" sandbox="allow-scripts allow-modals allow-popups allow-forms"></iframe>'); pane.insertBefore(f, pane.firstChild) }   // recreate — it was removed while hidden
