  const _keysOpen = { funcs: false, nums: false, syms: false }; let _keysMore = false, _keysRecent = []   // (Sum 2026-07-13) each has its OWN pit button now (ƒ · { } · 123) — toggles independently + STACKS in the drawer · _keysRecent = names you tapped, most-recent first (GOFAI ranking, no LLM)
