    try { editor.addCommand(monaco.KeyMod.Shift | monaco.KeyCode.Escape, () => { const n = document.activeElement; if (n) n.blur() }) } catch (_) {}   // ♿ ⇧Esc = GUARANTEED pop-out of the editor (plain Esc can be eaten by Monaco's widgets; Tab-moves-focus = Monaco's own ⌃⇧M)
