  // ── HOTKEYS (Sum 2026-07-13): appeal to muscle memory. Native Monaco keeps ⌘F find · ⌘/ comment · ⌃G go-to-line ·
  //    ⌘Z undo. We add the 0z pit controls on the conventions people already know (VS Code-ish). They ride the pit
  //    buttons (one click each), so there's ONE source of truth for what each does. ──
  const MC_HOTKEYS = [
    ['run',     'CtrlCmd+Enter',   () => { mcRun() }],
    ['console', 'CtrlCmd+KeyJ',    () => { const p = mcConsoleEl(); if (p && !p.hidden) { p.hidden = true; mcPreviewBlank() } else mcConsoleOpen() }],
    ['squiggy', 'Alt+KeyS',        () => toggleSquiggy()],
    ['fix',     'CtrlCmd+Shift+KeyF', () => clickPit('fix')],
    ['teach',   'CtrlCmd+Shift+KeyE', () => clickPit('teach')],
    ['diff',    'CtrlCmd+Shift+KeyD', () => clickPit('diff')],
    ['preview', 'CtrlCmd+Shift+KeyV', () => clickPit('preview')],
    ['save',    'CtrlCmd+KeyS',     () => clickPit('save')],
    ['saveout', 'CtrlCmd+Shift+KeyS', () => clickPit('saveout')],
    ['sandbox', 'CtrlCmd+Shift+KeyO', () => clickPit('sandbox')],
  ]
