  const node = h => { const d = document.createElement('div'); d.innerHTML = h.trim(); return d.firstElementChild }

  // the two drawn marks. one source for each colour — see the note above the sweep button.
  const SQUIGGLE_RED = '#e0413e', CHECK_GREEN = '#2fa84f'
  const icoSquiggle = () => `<svg viewBox="0 0 24 24" width="17" height="17" aria-hidden="true" focusable="false"><path d="M2 15 q3 -6 6 0 t6 0 t6 0" fill="none" stroke="${SQUIGGLE_RED}" stroke-width="2.6" stroke-linecap="round"/></svg>`
  const icoCheck = () => `<svg viewBox="0 0 24 24" width="17" height="17" aria-hidden="true" focusable="false"><path d="M4 12.5 l5.5 5.5 L20 5.5" fill="none" stroke="${CHECK_GREEN}" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`
  window.OZ_MARK = { squiggle: icoSquiggle, check: icoCheck }   // Fix's ✓ reads these too — one drawing, every surface
  // 🛑 monaco's stop — abort an in-flight run + keep the partial. WIRE-POINT: nothing
  // runs in monaco yet (it's the editor); this is the chrome for when the coder agent runs
  // file-surgery here. (resize is now the card's own bottom bar — Monaco automaticLayout relayouts.)
  function monacoStop() { if (window.setJewel) window.setJewel(card, 'off'); mcJewel() }

