  //    both call THIS. it REUSES the working PIT handlers (fix/teach/find/diff) by clicking their buttons —
  //    one place, no drift, no duplicated logic — and Monaco's own action for format. ──
  function mcAction(a) {
    if (!editor) return
    const pit = sel => { const b = card && card.querySelector(`.mc-pit-btn[data-pit="${sel}"]`); if (b) b.click() }
    if (a === 'goto') focusGoto()   // (Sum 2026-07-14) go-to-line is in the name bar now, not a pit button
    else if (a === 'fix' || a === 'teach' || a === 'find' || a === 'diff') pit(a)
    else if (a === 'format') editor.getAction('editor.action.formatDocument')?.run()
    else if (a === 'newfile') newBlank()
  }

  // ── the TYPO-FREE ⌘K palette (Sum 2026-07-11) — ONE fuzzy surface: actions + OPEN-A-FILE (no typing the
  //    name) + language. forgiving match, arrow/click, never have to type. the wishlist's unified palette. ──
  function mcPalette() {
    if (!window.OZ_PALETTE) return
    const itms = []
    ;[['🔧 Fix — coder cleans this file', 'fix'], ['🎓 Teach — tutor explains', 'teach'], ['＋ New file', 'newfile'],
      ['⌁ Format document', 'format'], ['🔍 Find + Replace', 'find'], ['🏁 Toggle diff', 'diff']]
      .forEach(a => itms.push({ group: 'actions', label: a[0], run: () => mcAction(a[1]) }))
    const sb = window.SANDBOX || {}
    Object.keys(sb).forEach(n => { const f = sb[n]; if (f && typeof f.data === 'string' && f.kind !== 'url') itms.push({ group: 'open a file', label: 'open  ' + n, hint: f.data.split('\n').length + ' lines', run: () => { if (window.monacoReveal) window.monacoReveal(n) } }) })
    ;['html', 'javascript', 'css', 'json', 'markdown', 'python', 'typescript'].forEach(l => itms.push({ group: 'language', label: 'language: ' + l, run: () => { if (editor) monaco.editor.setModelLanguage(editor.getModel(), l) } }))
    window.OZ_PALETTE.open(itms)
  }

