  const TOOL_AI = { fix: 1, teach: 1, squiggy: 1, devtools: 1 }   // (Sum 2026-07-14) the SOLO tools — only ƒ/{}/123 keys share a wing; these close each other when they share one
  const WING_ARROW = { left: '←', top: '↑', bottom: '↓', right: '→' }
