  let _fixEd = null, _fixThread = [], _fixCtrl = null, _fixAttach = [], _fixRO = null, _fixCode = [], _fixOrig = '', _fixDiff = null, _fixDiffIdx = -1, _fixScope = 'tab', _fixHL = false, _fixLevel = 'tidy'   // (Sum 2026-07-13) 🖊 highlighter = fix ONLY the selection · scope = background layers · _fixLevel = the aggression ▾ (light→nuke)
