    return `${collapseIcoHTML('fix')}${fsBtnHTML('fix')}${mcLevelDrop(FIX_LEVELS, _fixLevel, 'mc-fix-leveldrop')}${hlBtnHTML(_fixHL, 'data-fixhl')}${mcScopeDrop(_fixScope, 'data-fixscope', 'mc-fix-ctxdrop')}<button class="mc-fix-toprefresh" data-fixrefresh="1" title="re-run the fix at this level">↻</button>${fixNavHTML()}<button class="mc-fix-diff${fixDiffing() ? ' on' : ''}" data-fixdiff="1" title="diff the ORIGINAL vs the fix">◧ diff</button><button class="mc-fix-check" data-fixcheck="1" title="health check — the free mechanical pass, then a triage of what a machine cannot see">${(window.OZ_MARK ? window.OZ_MARK.check() : '✓')}</button>`
