      const lp = e.target.closest('.mc-sq-lv[data-lv]'); if (lp) { e.stopPropagation(); p.querySelector('.mc-sq-level').classList.remove('open'); _fixLevel = lp.dataset.lv; renderFixScope(); const L = FIX_LEVELS.find(x => x[0] === _fixLevel); if (L) fixSend(L[3], L[2]); return }   // pick → run the fix at that aggression
