    p.querySelector('.mc-fix-send').addEventListener('click', send)
    p.querySelector('.mc-fix-in').addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); send() } })
    p.querySelector('.mc-fix-apply').addEventListener('click', fixApply)
