  function fixOpen() { ensureFixSpace(); excludeAI('fix'); const p = fixEl(); if (!p) return; p.hidden = false; _fixOrig = editor ? editor.getValue() : ''; ensureFixEditor(); if (_fixEd) _fixEd.layout(); renderFixScope(); syncToolPitBtns() }
  function toggleFixSpace() { ensureFixSpace(); const p = fixEl(); if (!p) return; if (!p.hidden) { p.hidden = true; syncToolPitBtns(); syncWings(); return } fixOpen(); fixHealthReport() }
  function fixToEditor(code) { if (code == null) return; ensureFixEditor(); if (_fixEd) { _fixEd.setValue(code); fixRevealFirstChange() } }
  function fixRevealFirstChange() {   // open scrolled to the LATEST change vs the original (Sum 2026-07-12)
    if (!_fixEd) return
    const orig = (_fixOrig || '').split('\n'), mod = _fixEd.getValue().split('\n')
    let ln = 1; for (let i = 0; i < mod.length; i++) { if (mod[i] !== orig[i]) { ln = i + 1; break } }
    _fixEd.revealLineNearTop(ln); _fixEd.setPosition({ lineNumber: ln, column: 1 })
  }
