    const label = op.where === 'beginning' ? 'prepend → top' : op.where === 'end' ? 'append → end' : 'insert → after line ' + op.where
    return `<div class="mc-fix-op"><div class="mc-fix-op-h">＋ ${label}${ln > 0 ? ' · at line ' + ln : ''}</div><pre class="mc-fix-op-new">${sqEsc(op.content)}</pre></div>`
